# Build mapping from first_name to emails (there might be multiple)
from collections import defaultdict
name_to_emails=defaultdict(set)
for c in contacts:
    fn=(c.get('first_name') or '').strip()
    em=(c.get('email') or '').strip().lower()
    if fn and em:
        name_to_emails[fn].add(em)

print('names in contacts that match share names:')
for n in shares.keys():
    print(n, name_to_emails.get(n, set()))

# Determine which share-holders already paid by email match
paid_names=set()
for n,email_set in name_to_emails.items():
    # email_set may contain multiple; if any email paid, consider name paid
    if any(e in paid_sender_emails for e in email_set):
        paid_names.add(n)
print('paid_names_by_phone_mapping', paid_names)

# Build recipients: names in shares not in paid_names, but with unique email
recipients=[]
for n,amt in shares.items():
    email_set=name_to_emails.get(n,set())
    # only proceed if we can identify email unambiguously
    if n in paid_names:
        continue
    if len(email_set)!=1:
        recipients.append((n,'AMBIGUOUS',amt,len(email_set),sorted(email_set)))
    else:
        recipients.append((n,next(iter(email_set)),amt))
print('recipients info', recipients)

